package com.EOT.project.controller;
import com.EOT.project.dto.request.CategoryRequestDTO; import com.EOT.project.dto.response.CategoryResponseDTO; import com.EOT.project.service.CategoryService; import java.util.UUID; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.http.HttpStatus; import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class CategoryControllerTest { @Mock CategoryService service; @InjectMocks CategoryController controller;
 @Test void delegatesCrudOperations() { UUID id=UUID.randomUUID(); var dto=new CategoryRequestDTO("General","x"); var response=CategoryResponseDTO.builder().categoryId(id).build(); when(service.create(dto)).thenReturn(response); assertThat(controller.createCategory(dto).getStatusCode()).isEqualTo(HttpStatus.CREATED); controller.deleteCategory(id); verify(service).delete(id); } }
